practiceProblems.solutionCode:
public class Main {
    public static void main(String[] args) {
        int tier = 1, points = 50;
        if (tier == 1) {
            if (points >= 100) {
                System.out.println("Tier 1: VIP Member");
            } else {
                System.out.println("Tier 1: Base Member");
            }
        }
    }
}

